import pandas as pd

def clean(df):
    df = df.copy()
    # remove exact duplicate rows
    df = df.drop_duplicates()
    # standardise sex labels
    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype(str).str.strip().str.lower()
        df = df[df['sex'].isin(['male', 'female'])]
    # parse body_mass_g which is stored as text with commas
    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False)
        df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
        df = df.dropna(subset=['body_mass_g'])
        df = df[(df['body_mass_g'] >= 2500) & (df['body_mass_g'] <= 6500)]
    # keep penguin_id unique
    if 'penguin_id' in df.columns:
        df = df.drop_duplicates(subset=['penguin_id'])
    return df

def answer(df):
    if 'sex' not in df.columns or 'body_mass_g' not in df.columns:
        return {}
    out = df.groupby('sex')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in out.items()}
